@startuml

class EBike {
  + bikeId : string
  + modelName : string
  + manufactureDate : date
}

class Frame {
  + material : string
  + frameId : string
}

class DriveSystem {
  + driveType : string
}

class Motor {
  + powerOutput : int
  + motorType : string
}

class Controller {
  + state : ControllerState
}

class BasicController {}

class AdvancedController {
  + nextInspectionDate : date
}

class Battery {
  + storedEnergyWh : int
  + capacity : int
}

class Wheel {
  + wheelSize : int
  + tirePressure : float
}

enum ControllerState {
  On
  Off
  Charging
}

EBike "1" *-- "1" Frame
EBike "1" *-- "1" DriveSystem
EBike "1" *-- "1" Controller
EBike "0..1" o-- "1" Battery
Frame "1" *-- "2" Wheel
DriveSystem "1" *-- "1" Motor
BasicController --|> Controller
AdvancedController --|> Controller
Controller --> Battery : controls
Controller --> DriveSystem : commands

@enduml

